        buf = ["<", self.name]
        for name, value in self.attrs.items():
            buf.append(' %s="%s"' % (name, self.escape(value)))
        if self.children:
            buf.append(">")
            content = self._content(indent)
            if content:
                buf.append("\n")
                buf.append(content)
                buf.append("\n")
                buf.append(" " * indent)
            buf.append("</%s>" % self.name)
        else:
            buf.append("/>")
        return "".join(buf)

